const fail = (msg) => {
  const e = new Error(msg)
  e.isConfigError = true
  throw e
}

const INT = /^[+-]?[0-9]+(_[0-9]+)*$/
const FLOAT = /^[+-]?[0-9]+(_[0-9]+)*(\.[0-9]+(_[0-9]+)*)?([eE][+-]?[0-9]+(_[0-9]+)*)?$/
const isWs = (c) => c === ' ' || c === '\t'
const isBare = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)

const newTable = () => ({ t: 'table', m: new Map(), hdr: false })

function walk(tbl, names, base) {
  let path = base.slice()
  for (const name of names) {
    path.push(name)
    let c = tbl.m.get(name)
    if (!c) {
      c = newTable()
      tbl.m.set(name, c)
    } else if (c.t === 'array' && c.aot) c = c.items[c.items.length - 1]
    else if (c.t !== 'table') fail(`${path.join('.')} is not a table`)
    tbl = c
  }
  return tbl
}

function assign(tbl, names, value, base) {
  const parent = walk(tbl, names.slice(0, -1), base)
  const last = names[names.length - 1]
  if (parent.m.has(last)) fail(`key ${[...base, ...names].join('.')} is defined twice`)
  parent.m.set(last, value)
}

class Line {
  constructor(s) {
    this.s = s
    this.i = 0
  }
  get c() {
    return this.s[this.i]
  }
  ws() {
    while (isWs(this.c)) this.i++
  }
  // at end of line or at a comment start
  atEnd() {
    return this.c === undefined || this.c === '#' || this.c === ';'
  }
  str(q) {
    this.i++
    let out = ''
    for (;;) {
      const c = this.c
      if (c === undefined) fail('unterminated string')
      if (c === q) {
        this.i++
        return out
      }
      if (q === '"' && c === '\\') {
        this.i++
        const e = this.c
        if (e === undefined) fail('unterminated string')
        const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
        if (Object.hasOwn(map, e)) out += map[e]
        else if (e === 'u') {
          const h = this.s.slice(this.i + 1, this.i + 5)
          if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16))
          this.i += 4
        } else fail(`invalid escape \\${String.fromCodePoint(this.s.codePointAt(this.i))}`)
        this.i++
        continue
      }
      out += c
      this.i++
    }
  }
  name() {
    const c = this.c
    if (c === '"' || c === "'") return this.str(c)
    const st = this.i
    while (isBare(this.c)) this.i++
    if (st === this.i) fail('expected a name')
    return this.s.slice(st, this.i)
  }
  dotted() {
    const names = []
    this.ws()
    names.push(this.name())
    for (;;) {
      this.ws()
      if (this.c !== '.') return names
      this.i++
      this.ws()
      names.push(this.name())
    }
  }
  value(base) {
    this.ws()
    const c = this.c
    if (c === undefined || c === '#' || c === ';' || c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"') return { t: 'string', v: this.str('"') }
    if (c === "'") return { t: 'string', v: this.str("'") }
