    if (tok === 'true' || tok === 'false') return { t: 'boolean', v: tok === 'true' }
    if (INT.test(tok)) return { t: 'integer', v: Number(tok.replaceAll('_', '')) }
    if (FLOAT.test(tok)) return { t: 'float', v: Number(tok.replaceAll('_', '')) }
