  }
  array(base) {
    this.i++
    const items = []
    for (;;) {
      this.ws()
      if (this.c === ']') {
        this.i++
        return { t: 'array', items, aot: false }
      }
      if (this.atEnd()) fail('unterminated array')
      items.push(this.value(base))
      this.ws()
      if (this.c === ',') this.i++
      else if (this.c === ']') continue
      else fail('unterminated array')
    }
  }
  inline(base) {
    this.i++
    const tbl = newTable()
    this.ws()
    if (this.c === '}') {
      this.i++
      return tbl
    }
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated inline table')
      const names = this.dotted()
      this.ws()
      if (this.c !== '=') {
        if (this.atEnd()) fail('unterminated inline table')
        fail('expected = in an inline table')
