      this.i++
      const v = this.value([...base, ...names])
      assign(tbl, names, v, base)
      this.ws()
      if (this.c === ',') this.i++
      else if (this.c === '}') {
        this.i++
        return tbl
      } else fail('unterminated inline table')
    }
  }
}

export function parseDocument(lines) {
  const root = newTable()
  let cur = root
  let curPath = []
  for (let n = 0; n < lines.length; n++) {
    try {
      const L = new Line(lines[n])
      L.ws()
      if (L.c === undefined || L.c === '#' || L.c === ';') continue
      if (L.c === '[') {
        const dbl = L.s[L.i + 1] === '['
        L.i += dbl ? 2 : 1
        const names = L.dotted()
        if (L.c !== ']') fail('unterminated table header')
        L.i++
        if (dbl) {
          if (L.c !== ']') fail('unterminated table header')
          L.i++
        }
        L.ws()
        if (!L.atEnd()) fail('trailing text after a table header')
        const parent = walk(root, names.slice(0, -1), [])
        const last = names[names.length - 1]
        const path = names.join('.')
        const ex = parent.m.get(last)
        if (dbl) {
          const fresh = newTable()
          if (!ex) parent.m.set(last, { t: 'array', items: [fresh], aot: true })
          else if (ex.t === 'array' && ex.aot) ex.items.push(fresh)
          else fail(`${path} is not an array of tables`)
          cur = fresh
        } else {
          if (!ex) {
            cur = newTable()
            parent.m.set(last, cur)
          } else if (ex.t !== 'table') fail(`${path} is not a table`)
          else {
            if (ex.hdr) fail(`table ${path} is defined twice`)
            cur = ex
          }
          cur.hdr = true
        }
        curPath = names
        continue
      }
      const names = L.dotted()
      if (L.c !== '=') fail('expected key = value')
      L.i++
      const v = L.value([...curPath, ...names])
      L.ws()
      if (!L.atEnd()) fail('trailing text after a value')
      assign(cur, names, v, curPath)
    } catch (e) {
      if (e && e.isConfigError) e.line = n + 1
      throw e
    }
  }
  return root
}
